/**
 * The OmniHarness app client (Spec 011 FR-023, FR-025): `window.omni`, made
 * by the platform shim (omni-shim.js) before your code runs.
 *
 * Your app never touches the network. It asks the host page for a source by
 * the NAME your omni-app.json gives it, and gets that source's projected,
 * read-only data back:
 *
 *   const r = await omni.data("calendar");
 *   if (r.state === "fresh") render(r.data.items);
 *
 * The kit generates `OmniSources` from your manifest (each name mapped to its
 * catalog entry's data), so `omni.data("calendar")` is typed. Without it,
 * every name is a string and every `data` is `unknown`.
 *
 * Every tile handles all four states; see README.md beside this file for the
 * words to use.
 *
 * The app's CSP has Trusted Types with no policy (`require-trusted-types-for
 * 'script'; trusted-types 'none'`): build the DOM with createElement and
 * textContent (React does); innerHTML, insertAdjacentHTML, srcdoc,
 * document.write and other HTML-from-string APIs throw, and the shim refuses
 * frame elements of any kind.
 */

export type SourceState = "fresh" | "empty" | "not_connected" | "failed";
export type Theme = "light" | "dark";

/** One source's answer. */
export interface SourceResult<D = unknown> {
  source: string;
  /**
   * fresh: there is data. empty: the source answered with nothing.
   * not_connected: its account is not connected (offer omni.connect).
   * failed: it could not be read; `reason` says why, and `data` is the last
   * good data (then `stale` is true) or null.
   */
  state: SourceState;
  data: D | null;
  /** When `data` was fetched (ISO 8601), null when never. */
  fetched_at: string | null;
  /** Older than twice the source's refresh interval, or last good data. */
  stale: boolean;
  /** Only for `failed`: why, in words (≤ 300 characters). */
  reason: string | null;
}

/** Data of each catalog entry (specs/011-apps/api.md). Only the fields your
 * manifest selected are present in each item. */
export interface CatalogData {
  "googlecalendar.events_today": {
    items: Partial<{
      title: string;
      /** A time with its offset, or a date ("2026-11-13") when all_day. */
      start: string;
      end: string;
      all_day: boolean;
    }>[];
  };
  "github.pr_search": {
    items: Partial<{
      repo: string;
      number: number;
      title: string;
      updated_at: string;
      merged_at: string | null;
      link: string;
    }>[];
    /** The search had more results than the cap: say "20+". */
    more?: boolean;
    /** Results left out because their repository could not be placed. */
    dropped?: number;
  };
  "omni.ledger.today": {
    items: Partial<{
      bucket: "moved" | "stuck" | "overdue";
      task: string;
      project: string;
      status: string;
      due_date: string | null;
      link: string;
    }>[];
  };
  "omni.sessions.active": {
    items: Partial<{
      tool: string;
      title: string;
      display_state: "working" | "waiting-on-user";
      known: "observed" | "inferred";
      since: string;
    }>[];
  };
  "omni.automations.recent": {
    items: Partial<{
      rule: string;
      last_run: string | null;
      /** delivered | suppressed | queued | expired | failed, or null. */
      outcome: string | null;
      /** Null for a rule that runs on events (trigger "event"). */
      next_run: string | null;
      trigger: "schedule" | "event";
    }>[];
  };
  "gmail.unread_subjects": {
    count: number;
    count_capped: boolean;
    items: Partial<{ subject: string; received_at: string; link: string }>[];
  };
}

/**
 * Your sources: name → data. Generated by the kit from omni-app.json, for
 * example `interface OmniSources { calendar: CatalogData["googlecalendar.events_today"] }`.
 */
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface OmniSources {}

type Known = keyof OmniSources & string;
export type SourceName = [Known] extends [never] ? string : Known;
export type DataOf<K extends string> = K extends Known
  ? OmniSources[K]
  : unknown;

/** The standard words for a tile (README.md). */
export interface TileWords {
  /** "updated 4 min ago", "Nothing today", "Not connected", "Can't tell". */
  label: string;
  /** "May be out of date", the failure reason, or "". */
  detail: string;
}

export interface Omni {
  /** Resolves once the host has handed over the app's channel. */
  readonly ready: Promise<{ app: string; version: number; theme: Theme }>;
  /** A source's latest data (the host answers from its cache when warm). */
  data<K extends SourceName>(name: K): Promise<SourceResult<DataOf<K>>>;
  /** Ask for a refetch now (still at most one upstream call a minute). */
  refresh<K extends SourceName>(name: K): Promise<SourceResult<DataOf<K>>>;
  /**
   * Open a link: https on a host your sources' catalog entries declare, or a
   * /workspace/... path. Anything else is refused. Plain <a href> clicks are
   * routed here for you. Returns false if the message itself was invalid.
   */
  open(url: string): boolean;
  /** Show the host's Connect sheet for a source in `not_connected`. */
  connect(name: SourceName): boolean;
  /** Called now with the current theme (if known) and on every change. The
   * shim also toggles `.dark` on <html>. Returns an unsubscribe function. */
  onTheme(fn: (theme: Theme) => void): () => void;
  /** A source the host refreshed on its own (a poll, after Connect). */
  onUpdate(fn: (name: SourceName, result: SourceResult) => void): () => void;
  /** The host refused a message (the reason code). */
  onError(fn: (reason: string) => void): () => void;
  readonly theme: Theme | null;
  /** "just now", "4 min ago", "3 h ago", "2 days ago". */
  ago(iso: string | null): string;
  /** The standard words for a tile in its state. */
  describe(result: SourceResult | null | undefined): TileWords;
}

declare global {
  interface Window {
    readonly omni: Omni;
  }
  const omni: Omni;
}
